-- Agrolink: base separada de agroindústrias PEAF.
-- Importação aditiva e repetível da mesma planilha. Não apaga pedidos/estoque.
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS agrolink_produtores CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE agrolink_produtores;
CREATE TABLE IF NOT EXISTS peaf_fontes (
 id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
 arquivo VARCHAR(200) NOT NULL,
 aba VARCHAR(40) NOT NULL,
 referencia VARCHAR(80) NOT NULL,
 total_registros INT UNSIGNED NOT NULL,
 importado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS produtores (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 fonte_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 linha_origem INT UNSIGNED NOT NULL,
 numero_origem VARCHAR(30) NOT NULL,
 nome VARCHAR(200) NOT NULL,
 municipio VARCHAR(120) NOT NULL,
 processamento TEXT NOT NULL,
 data_inclusao DATE NULL,
 registro_peaf VARCHAR(40) NOT NULL,
 licenciamento VARCHAR(100) NOT NULL,
 ultima_atualizacao DATE NULL,
 classificacao VARCHAR(100) NOT NULL,
 alerta_fonte TEXT NULL,
 originais_json LONGTEXT NOT NULL,
 UNIQUE KEY origem_unica (fonte_id,linha_origem),
 INDEX idx_municipio(municipio),
 INDEX idx_classificacao(classificacao),
 INDEX idx_licenciamento(licenciamento),
 INDEX idx_peaf(registro_peaf),
 FOREIGN KEY(fonte_id) REFERENCES peaf_fontes(id)
) ENGINE=InnoDB;
START TRANSACTION;
ON DUPLICATE KEY UPDATE linha_origem=VALUES(linha_origem);
ON DUPLICATE KEY UPDATE linha_origem=VALUES(linha_origem);
ON DUPLICATE KEY UPDATE linha_origem=VALUES(linha_origem);
